def solution(board, word):
    m, n = len(board), len(board[0])
    def dfs(r, c, idx):
        if idx == len(word): return True
        if not (0 <= r < m and 0 <= c < n) or board[r][c] != word[idx]:
            return False
        temp = board[r][c]
        board[r][c] = '#'
        for dr, dc in [(1,0), (-1,0), (0,1), (0,-1)]:
            if dfs(r + dr, c + dc, idx + 1):
                board[r][c] = temp
                return True
        board[r][c] = temp
        return False
    for r in range(m):
        for c in range(n):
            if dfs(r, c, 0):
                return True
    return False
